    "audit_result": {
      "property_id": "PROP-stem-bot-v21-inv-003",
      "classification": "potential-vulnerability",
      "code_path": "src/lib/actions/teams.ts::updateTeam::L78-100",
      "proof_trace": "The only validation on `discord_role_id` in `teamSchema` is `z.string().min(1)` — a structural non-empty check with no allowlist membership test. No code anywhere in the actions layer cross-references the supplied `discord_role_id` against `generation_roles` or any bot-confirmed managed role set before writing to the database. Proof fails because all code paths that persist or mutate a team's `discord_role_id` (`createTeam`, `updateTeam`) bypass the required semantic guard entirely.",
      "attack_scenario": "An attacker who gains admin access (feasible via the documented Supabase RPC auth-bypass in this system) calls `updateTeam` with `discord_role_id` set to a high-privilege Discord role ID (e.g., server admin or moderator). On the next `syncDiscordRoles` call for any team member, the Discord bot reads the DB and assigns that arbitrary role, escalating Discord privileges for all members of the targeted team.",
      "checklist_id": "PROP-stem-bot-v21-inv-003"
    },
    "text": "removeRole must validate discord_role_id against an allowlist of managed roles.",
    "assertion": "forall req: removeRole(uid, role_id) => role_id in managed_roles_allowlist",
    "covers": "SG-012_removeRole",
    "severity": "CRITICAL",
    "type": "invariant"
  }
}

