1	import { Request, Response } from 'express';
2	import { getMember, addRoleToMember, removeRoleFromMember, getAllDiscordRoles } from '../utils/discord';
3	import { logger } from '../utils/logger';
4	import { 
5	  RoleAssignRequest, 
6	  RoleAssignResponse, 
7	  RoleRemoveRequest, 
8	  RoleRemoveResponse,
9	  DiscordRoleListResponse 
10	} from '../types/api';
11	
12	// POST /api/roles/assign - ロール付与
13	export const assignRole = async (req: Request, res: Response): Promise<void> => {
14	  try {
15	    const { discord_uid, discord_role_id } = req.body as RoleAssignRequest;
16	
17	    if (!discord_uid || !discord_role_id) {
18	      res.status(400).json({ 
19	        success: false, 
20	        error: 'discord_uid and discord_role_id are required' 
21	      });
22	      return;
23	    }
24	
25	    // Discordメンバーを取得
26	    const member = await getMember(discord_uid);
27	    if (!member) {
28	      res.status(404).json({ success: false, error: 'Discord member not found' });
29	      return;
30	    }
31	
32	    // ロールを付与
33	    const success = await addRoleToMember(member, discord_role_id);
34	    if (!success) {
35	      res.status(500).json({ success: false, error: 'Failed to assign role' });
36	      return;
37	    }
38	
39	    const response: RoleAssignResponse = { success: true };
40	    logger.info(`Role ${discord_role_id} assigned to ${discord_uid}`);
41	    res.json(response);
42	  } catch (error) {
43	    logger.error('Error in assignRole', error);
44	    res.status(500).json({ success: false, error: 'Internal server error' });
45	  }
46	};
47	
48	// POST /api/roles/remove - ロール削除
49	export const removeRole = async (req: Request, res: Response): Promise<void> => {
50	  try {
51	    const { discord_uid, discord_role_id } = req.body as RoleRemoveRequest;
52	
53	    if (!discord_uid || !discord_role_id) {
54	      res.status(400).json({ 
55	        success: false, 
56	        error: 'discord_uid and discord_role_id are required' 
57	      });
58	      return;
59	    }
60	
61	    // Discordメンバーを取得
62	    const member = await getMember(discord_uid);
63	    if (!member) {
64	      res.status(404).json({ success: false, error: 'Discord member not found' });
65	      return;
66	    }
67	
68	    // ロールを削除
69	    const success = await removeRoleFromMember(member, discord_role_id);
70	    if (!success) {
71	      res.status(500).json({ success: false, error: 'Failed to remove role' });
72	      return;
73	    }
74	
75	    const response: RoleRemoveResponse = { success: true };
76	    logger.info(`Role ${discord_role_id} removed from ${discord_uid}`);
77	    res.json(response);
78	  } catch (error) {
79	    logger.error('Error in removeRole', error);
80	    res.status(500).json({ success: false, error: 'Internal server error' });
81	  }
